if(order?.paymentToken){
  const sandboxBox=document.createElement('section');
  sandboxBox.className='midtrans-box';
  sandboxBox.innerHTML='<div><span class="pill">MIDTRANS SANDBOX</span><h2>Coba pembayaran seperti toko nyata</h2><p>Gunakan simulator atau kredensial pengujian Midtrans. Jangan membayar menggunakan uang, rekening, QRIS, atau aplikasi bank asli.</p></div><button class="btn" id="midtransPay" type="button">Bayar dengan Midtrans Sandbox</button><p class="midtrans-message" id="midtransMessage" aria-live="polite"></p>';
  document.querySelector('.actions').before(sandboxBox);
  const style=document.createElement('style');
  style.textContent='.midtrans-box{margin-top:20px;padding:18px;border:1px solid #d7c28f;border-radius:16px;background:#fff9ec}.midtrans-box h2{margin:10px 0 4px}.midtrans-box p{margin:0 0 14px;color:#795a2d;font-size:.88rem}.midtrans-box .btn{width:100%}.midtrans-message{min-height:1.3em;margin:10px 0 0!important}';
  document.head.append(style);
  const payButton=document.querySelector('#midtransPay'),payMessage=document.querySelector('#midtransMessage');
  if(order.status!=='pending'){payButton.disabled=true;payButton.textContent=order.status==='paid'?'Pembayaran Midtrans berhasil':order.status==='expired'?'Pembayaran kedaluwarsa':'Pembayaran sudah selesai'}
  payButton.addEventListener('click',async()=>{payButton.disabled=true;payButton.textContent='Menghubungkan ke Midtrans…';payMessage.textContent='';try{const response=await fetch('/api/midtrans/create',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({orderId:order.id,token:order.paymentToken})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Midtrans Sandbox belum tersedia');location.assign(data.redirectUrl)}catch(error){payMessage.textContent=error.message;payButton.disabled=false;payButton.textContent='Bayar dengan Midtrans Sandbox'}});
  async function refreshMidtrans(attempt=0){try{const response=await fetch(`/api/midtrans/${encodeURIComponent(order.id)}/status?token=${encodeURIComponent(order.paymentToken)}`),data=await response.json();if(!response.ok)throw new Error(data.error||'Status belum tersedia');order.status=data.orderStatus;order.midtransMethod=data.payment?.method||'Midtrans Snap';if(!instructions[order.method])order.method='Virtual Account';if(order.status==='paid')order.paidAt=data.payment?.paidAt||new Date().toISOString();save();render();if(order.status!=='pending'){payButton.disabled=true;payButton.textContent=order.status==='paid'?'Pembayaran Midtrans berhasil':order.status==='expired'?'Pembayaran kedaluwarsa':'Pembayaran sudah selesai'}if(order.status==='pending'&&attempt<5){payMessage.textContent='Menunggu notifikasi pembayaran dari Midtrans…';setTimeout(()=>refreshMidtrans(attempt+1),2000)}else payMessage.textContent=order.status==='paid'?'Pembayaran sandbox berhasil disinkronkan.':order.status==='pending'?'Pembayaran masih menunggu penyelesaian di Midtrans Sandbox.':'Status Midtrans telah disinkronkan.'}catch(error){payMessage.textContent=error.message}}
  if(new URLSearchParams(location.search).get('midtrans')==='return')refreshMidtrans();
}
